xpath.script:
(function () {
    try {
        var KEY = 'ldDarkMode';
        var RELOAD_FLAG = 'ldDarkReloaded';
        var cookie = document.cookie.split(';').map(function (c) {
            return c.trim();
        });
        var cookieMode = null;
        cookie.forEach(function (c) {
            if (c.indexOf('color_scheme=') === 0) {
                cookieMode = c.split('=')[1];
            }
        });
        var raw = null;
        try { raw = window.localStorage.getItem(KEY); } catch (e) {}
        var stored = null;
        try { stored = raw ? JSON.parse(raw) : null; } catch (e) {}
        var VALID = ['light', 'dark', 'auto', 'schedule'];
        var pref = (stored && VALID.indexOf(stored.mode) >= 0) ? stored.mode : 'auto';
        function clampHour(v, fallback) {
            if (typeof v !== 'number' || isNaN(v) || v < 0 || v >= 24) {
                return fallback;
            }
            return v;
        }
        var start = clampHour(stored && stored.scheduleStart, 19);
        var end = clampHour(stored && stored.scheduleEnd, 7);
        var effective = 'light';
        if (pref === 'dark') { effective = 'dark'; }
        else if (pref === 'light') { effective = 'light'; }
        else if (pref === 'auto') {
            var mq = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)');
            effective = (mq && mq.matches) ? 'dark' : 'light';
        }
        else if (pref === 'schedule') {
            var now = new Date();
            var h = now.getHours() + now.getMinutes() / 60;
            var inRange = (start === end) ? false
                : (start < end ? (h >= start && h < end)
                              : (h >= start || h < end));
            effective = inRange ? 'dark' : 'light';
        }
        if (effective === 'dark') {
            document.documentElement.setAttribute('data-ld-dark', '1');
        } else {
            document.documentElement.removeAttribute('data-ld-dark');
        }
        if (cookieMode !== effective) {
            var reloaded = false;
            try { reloaded = window.sessionStorage.getItem(RELOAD_FLAG) === '1'; } catch (e) {}
            var secureFlag = window.location.protocol === 'https:' ? '; Secure' : '';
            document.cookie = 'color_scheme=' + effective +
                '; path=/; max-age=' + (60 * 60 * 24 * 365) + '; SameSite=Lax' + secureFlag;
            if (!reloaded) {
                try { window.sessionStorage.setItem(RELOAD_FLAG, '1'); } catch (e) {}
                window.location.reload();
            }
        } else {
            try { window.sessionStorage.removeItem(RELOAD_FLAG); } catch (e) {}
        }
    } catch (err) {
        // Never break page load because of dark mode.
    }
})();
